// 职责：创建渲染器/场景/相机、管理 PointerLock、驱动每帧 update、
//        回合流程（波次刷怪 → 全清 → 下一波 → 通关/阵亡结算）
// 经典脚本（非 ES Module）：THREE / CONFIG / GameMap / Player / WeaponSystem /
//        Enemy / PickupSystem / HUD / AudioFX 均由前置脚本挂到 window 提供

class Game {
  constructor() {
    this.hud = new HUD();
    this.audio = new AudioFX();
    this.hud.audio = this.audio;

    // 横屏包装层：小工具容器/WebView 常被宿主 App 锁定为竖屏、无法跟随设备旋转
    //（skill 文档明确 requestFullscreen / orientation.lock / PointerLock 均不可用），
    // 把全部游戏 DOM 包进一层，视口为竖屏时整体 CSS 旋转 90° 强制横屏
    const gameRoot = document.createElement('div');
    gameRoot.id = 'gameRoot';
    for (const el of Array.from(document.body.children)) {
      if (el.tagName !== 'SCRIPT') gameRoot.appendChild(el);
    }
    document.body.appendChild(gameRoot);
    this.gameRoot = gameRoot;
    this._rotated = false;

    // Three 基础设施
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    // 像素比上限：触屏设备 1.5（高 DPR 手机像素压力最大，降级显著提帧率），桌面 2
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, isTouch ? 1.5 : 2));
    this.renderer.shadowMap.enabled = true;

